{
  "aggregate_id": "DEF-NRS-484A-320::vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The exception for devices moved by human power describes the contract's human-powered bicycle."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The admitting clause reaches a motor vehicle designed to carry passengers, and no exception names or describes that class."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a transporting device, so the admitting clause reaches no member."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The admitting clause reaches vehicles carrying persons or property, and neither commercial mass nor commercial licensing brings the class within an exception."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The exception expressly names electric bicycles, matching the class identified through the jurisdiction's electric-bicycle taxonomy."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The exception expressly names an electric scooter, the class described by the contract."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "The admitting clause reaches transporting devices designated as emergency vehicles without requiring responding conduct, and no exception removes that class."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting vehicle falls within the admitting words for devices transporting persons or property, and no exception removes that class."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The admitting clause reaches the jurisdiction-classed engine- or motor-propelled moped, whose posted definition expressly distinguishes it from electric bicycles and electric scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The admitting clause reaches the contract's self-propelled non-rail transporting vehicles, and no exception names or describes that class."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The admitting clause reaches motor vehicles carrying riders on two or three wheels, and no exception names or describes that class."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "The admitting clause reaches transporting vehicles in official or contracted road service, and no exception removes that class."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "Every alternative in the contract describes a person rather than the device carrying that person, so the device-only admitting clause reaches no member."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person with specified assistance rather than a transporting device, so the admitting clause reaches no member."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract's description of on-track equipment does not establish the exception's requirement that a device be used exclusively upon stationary rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The admitting clause reaches buses carrying school children, and no exception removes that class."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The admitting clause reaches passenger vehicles for hire, and no exception names or describes that class."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Both the bus and lengthened passenger-vehicle alternatives are transporting devices reached by the admitting clause, with no exception removing the class."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The admitting words expressly reach devices by which persons or property may be transported or drawn, encompassing the contract's drawn vehicle or combination."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The admitting clause reaches buses transporting passengers in public transit service, and no exception removes that class."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The admitting clause reaches motor vehicles built to carry goods, and no exception names or describes that class."
    }
  ]
}

